export const FIX_GUIDES: Record<string, { title: string; html: string; markdown: string }> = {
 "basics.homepage_ttfb": {
  "title": "Homepage responds quickly",
  "html": "<p>Your homepage was slow to start responding, a sign that every page and API call is slow.</p>\n<h2>How to fix</h2>\n<p>Enable full-page caching and a CDN; check for slow plugins or database queries.</p>\n<h2>WooCommerce</h2>\n<p>Use a caching plugin (or your host&#39;s built-in cache), enable object caching, and audit slow plugins with Query Monitor.</p>\n<h2>How to verify</h2>\n<p>Measure time to first byte with <code>curl -s -o /dev/null -w &#39;%{time_starttransfer}\\n&#39; https://&lt;your-domain&gt;/</code>.</p>\n<h2>Spec reference</h2>\n<p>General web performance practice.</p>\n",
  "markdown": "# Homepage responds quickly\n\nYour homepage was slow to start responding, a sign that every page and API call is slow.\n\n## How to fix\n\nEnable full-page caching and a CDN; check for slow plugins or database queries.\n\n## WooCommerce\n\nUse a caching plugin (or your host's built-in cache), enable object caching, and audit slow plugins with Query Monitor.\n\n## How to verify\n\nMeasure time to first byte with `curl -s -o /dev/null -w '%{time_starttransfer}\\n' https://<your-domain>/`.\n\n## Spec reference\n\nGeneral web performance practice.\n"
 },
 "basics.https_redirect": {
  "title": "HTTP redirects to HTTPS",
  "html": "<p>Requests to <code>http://</code> should permanently redirect (301 or 308) to <code>https://</code>. Agents only use HTTPS, and links shared with <code>http://</code> should land on the secure site.</p>\n<h2>How to fix</h2>\n<p>Enable “Always use HTTPS” at your CDN or add a server rule redirecting all HTTP traffic to HTTPS with 301.</p>\n<h2>WooCommerce</h2>\n<p>Set both WordPress Address and Site Address to <code>https://</code> in Settings → General; Cloudflare&#39;s “Always Use HTTPS” or your host&#39;s SSL setting adds the redirect.</p>\n<h2>How to verify</h2>\n<p><code>curl -sI http://&lt;your-domain&gt;/</code> should show <code>301</code> and <code>location: https://...</code>.</p>\n<h2>Spec reference</h2>\n<p>General web practice; UCP requires HTTPS for profiles (UCP specification, <code>docs/specification/overview/index.md</code>, “Profile Requirements”).</p>\n",
  "markdown": "# HTTP redirects to HTTPS\n\nRequests to `http://` should permanently redirect (301 or 308) to `https://`. Agents only use HTTPS, and links shared with `http://` should land on the secure site.\n\n## How to fix\n\nEnable “Always use HTTPS” at your CDN or add a server rule redirecting all HTTP traffic to HTTPS with 301.\n\n## WooCommerce\n\nSet both WordPress Address and Site Address to `https://` in Settings → General; Cloudflare's “Always Use HTTPS” or your host's SSL setting adds the redirect.\n\n## How to verify\n\n`curl -sI http://<your-domain>/` should show `301` and `location: https://...`.\n\n## Spec reference\n\nGeneral web practice; UCP requires HTTPS for profiles (UCP specification, `docs/specification/overview/index.md`, “Profile Requirements”).\n"
 },
 "basics.robots_allows_products": {
  "title": "robots.txt allows product pages",
  "html": "<p>Your robots.txt blocks product URLs for CartProbeBot (and the rules shown probably block other agents too). CartProbe honours robots.txt, so those pages were not sampled.</p>\n<h2>How to fix</h2>\n<p>Remove <code>Disallow</code> rules covering product paths, or add an <code>Allow</code> for them. Keep blocking cart, checkout and account pages.</p>\n<h2>WooCommerce</h2>\n<p>Check robots.txt rules added by SEO or security plugins; <code>Disallow: /product/</code> is a common mistake.</p>\n<h2>How to verify</h2>\n<p>Use a robots.txt tester with a product URL and the user agent <code>CartProbeBot</code>.</p>\n<h2>Spec reference</h2>\n<p>RFC 9309; see also CartProbe&#39;s /bot page.</p>\n",
  "markdown": "# robots.txt allows product pages\n\nYour robots.txt blocks product URLs for CartProbeBot (and the rules shown probably block other agents too). CartProbe honours robots.txt, so those pages were not sampled.\n\n## How to fix\n\nRemove `Disallow` rules covering product paths, or add an `Allow` for them. Keep blocking cart, checkout and account pages.\n\n## WooCommerce\n\nCheck robots.txt rules added by SEO or security plugins; `Disallow: /product/` is a common mistake.\n\n## How to verify\n\nUse a robots.txt tester with a product URL and the user agent `CartProbeBot`.\n\n## Spec reference\n\nRFC 9309; see also CartProbe's /bot page.\n"
 },
 "basics.robots_present": {
  "title": "robots.txt is present",
  "html": "<p><code>/robots.txt</code> tells crawlers and agents what they may fetch and where your sitemaps are. It was missing or unreachable.</p>\n<h2>How to fix</h2>\n<p>Serve a robots.txt at the site root with at least <code>User-agent: *</code> and a <code>Sitemap:</code> line pointing at your sitemap.</p>\n<h2>WooCommerce</h2>\n<p>WordPress generates a virtual robots.txt; SEO plugins let you edit it. Make sure a physical file or security rule is not returning an error.</p>\n<h2>How to verify</h2>\n<p>Open <code>https://&lt;your-domain&gt;/robots.txt</code>.</p>\n<h2>Spec reference</h2>\n<p>RFC 9309 (Robots Exclusion Protocol).</p>\n",
  "markdown": "# robots.txt is present\n\n`/robots.txt` tells crawlers and agents what they may fetch and where your sitemaps are. It was missing or unreachable.\n\n## How to fix\n\nServe a robots.txt at the site root with at least `User-agent: *` and a `Sitemap:` line pointing at your sitemap.\n\n## WooCommerce\n\nWordPress generates a virtual robots.txt; SEO plugins let you edit it. Make sure a physical file or security rule is not returning an error.\n\n## How to verify\n\nOpen `https://<your-domain>/robots.txt`.\n\n## Spec reference\n\nRFC 9309 (Robots Exclusion Protocol).\n"
 },
 "basics.sitemap_found": {
  "title": "Product sitemap found",
  "html": "<p>CartProbe could not find a sitemap listing your products (it looks at robots.txt <code>Sitemap:</code> lines, <code>sitemap_index.xml</code>, <code>product-sitemap.xml</code> and <code>sitemap.xml</code>).</p>\n<h2>How to fix</h2>\n<p>Publish an XML sitemap that includes product URLs and reference it in robots.txt.</p>\n<h2>WooCommerce</h2>\n<p>Yoast and Rank Math generate <code>product-sitemap.xml</code> automatically; WordPress core provides <code>wp-sitemap.xml</code>. Add the sitemap URL to robots.txt.</p>\n<h2>How to verify</h2>\n<p>Open your sitemap and confirm product URLs are listed.</p>\n<h2>Spec reference</h2>\n<p>sitemaps.org protocol.</p>\n",
  "markdown": "# Product sitemap found\n\nCartProbe could not find a sitemap listing your products (it looks at robots.txt `Sitemap:` lines, `sitemap_index.xml`, `product-sitemap.xml` and `sitemap.xml`).\n\n## How to fix\n\nPublish an XML sitemap that includes product URLs and reference it in robots.txt.\n\n## WooCommerce\n\nYoast and Rank Math generate `product-sitemap.xml` automatically; WordPress core provides `wp-sitemap.xml`. Add the sitemap URL to robots.txt.\n\n## How to verify\n\nOpen your sitemap and confirm product URLs are listed.\n\n## Spec reference\n\nsitemaps.org protocol.\n"
 },
 "catalog.amounts_integer": {
  "title": "Prices use integer minor units",
  "html": "<p>UCP money amounts are integers in the currency&#39;s minor unit: $19.99 is <code>1999</code>, ¥1500 is <code>1500</code>. A decimal like <code>19.99</code> in an <code>amount</code> field is invalid and breaks price display and comparisons.</p>\n<h2>How to fix</h2>\n<p>Convert prices with exact arithmetic: <code>amount = round(price × 10^exponent)</code> where the exponent is 2 for USD/EUR/INR, 0 for JPY/KRW, 3 for KWD/BHD. Never send floats.</p>\n<h2>WooCommerce</h2>\n<p>If your plugin outputs decimals, update it or report the bug; WooCommerce stores prices as decimal strings, so the plugin must convert them.</p>\n<h2>How to verify</h2>\n<p>In the search response, every <code>amount</code> should be a whole number.</p>\n<h2>Spec reference</h2>\n<p><code>source/schemas/common/types/amount.json</code> (integer, minimum 0) and <code>price.json</code>.</p>\n",
  "markdown": "# Prices use integer minor units\n\nUCP money amounts are integers in the currency's minor unit: $19.99 is `1999`, ¥1500 is `1500`. A decimal like `19.99` in an `amount` field is invalid and breaks price display and comparisons.\n\n## How to fix\n\nConvert prices with exact arithmetic: `amount = round(price × 10^exponent)` where the exponent is 2 for USD/EUR/INR, 0 for JPY/KRW, 3 for KWD/BHD. Never send floats.\n\n## WooCommerce\n\nIf your plugin outputs decimals, update it or report the bug; WooCommerce stores prices as decimal strings, so the plugin must convert them.\n\n## How to verify\n\nIn the search response, every `amount` should be a whole number.\n\n## Spec reference\n\n`source/schemas/common/types/amount.json` (integer, minimum 0) and `price.json`.\n"
 },
 "catalog.has_results": {
  "title": "Search returns products",
  "html": "<p>A common search returned no products. If agents get empty results for ordinary words, they assume you do not sell those items.</p>\n<h2>How to fix</h2>\n<ul>\n<li>Make sure published, in-stock products are included in the search index the UCP endpoint uses.</li>\n<li>Support simple keyword matching on title and description at minimum.</li>\n</ul>\n<h2>WooCommerce</h2>\n<p>Check that the UCP plugin includes all published product types (simple, variable) and is not limited to a category.</p>\n<h2>How to verify</h2>\n<p>Search your catalog endpoint for a word that appears in several product titles.</p>\n<h2>Spec reference</h2>\n<p>UCP specification, <code>docs/specification/shopping/catalog/</code> (search.md, rest.md).</p>\n",
  "markdown": "# Search returns products\n\nA common search returned no products. If agents get empty results for ordinary words, they assume you do not sell those items.\n\n## How to fix\n\n- Make sure published, in-stock products are included in the search index the UCP endpoint uses.\n- Support simple keyword matching on title and description at minimum.\n\n## WooCommerce\n\nCheck that the UCP plugin includes all published product types (simple, variable) and is not limited to a category.\n\n## How to verify\n\nSearch your catalog endpoint for a word that appears in several product titles.\n\n## Spec reference\n\nUCP specification, `docs/specification/shopping/catalog/` (search.md, rest.md).\n"
 },
 "catalog.latency": {
  "title": "Catalog search is fast",
  "html": "<p>Search took too long. Agents answer shoppers in real time and time out slow calls.</p>\n<h2>How to fix</h2>\n<ul>\n<li>Add database indexes for searched fields or use a search engine.</li>\n<li>Limit the default page size (agents can request more with pagination).</li>\n</ul>\n<h2>WooCommerce</h2>\n<p>Use a search plugin with an index (e.g. a dedicated search service) rather than SQL <code>LIKE</code> queries over all products; enable object caching (Redis).</p>\n<h2>How to verify</h2>\n<p>Time the curl command from “Catalog search responds”; aim for under 1.5 seconds.</p>\n<h2>Spec reference</h2>\n<p>UCP specification, <code>docs/specification/shopping/catalog/</code> (search.md, rest.md).</p>\n",
  "markdown": "# Catalog search is fast\n\nSearch took too long. Agents answer shoppers in real time and time out slow calls.\n\n## How to fix\n\n- Add database indexes for searched fields or use a search engine.\n- Limit the default page size (agents can request more with pagination).\n\n## WooCommerce\n\nUse a search plugin with an index (e.g. a dedicated search service) rather than SQL `LIKE` queries over all products; enable object caching (Redis).\n\n## How to verify\n\nTime the curl command from “Catalog search responds”; aim for under 1.5 seconds.\n\n## Spec reference\n\nUCP specification, `docs/specification/shopping/catalog/` (search.md, rest.md).\n"
 },
 "catalog.product_fields": {
  "title": "Products include required fields",
  "html": "<p>Some products returned by search are missing fields the spec requires, or lack a product URL or variant availability that agents rely on.</p>\n<h2>How to fix</h2>\n<p>Required on each product: <code>id</code>, <code>title</code>, <code>description</code>, <code>price_range</code>, <code>variants</code>. Required on each variant: <code>id</code>, <code>title</code>, <code>description</code>, <code>price</code> (integer <code>amount</code> + <code>currency</code>). Strongly recommended: product <code>url</code> and variant <code>availability</code> (<code>{&quot;available&quot;: true}</code>).</p>\n<h2>WooCommerce</h2>\n<p>Fill in product descriptions in WooCommerce (empty descriptions are common) and make sure each variation has a price.</p>\n<h2>How to verify</h2>\n<p>Re-run the scan; evidence lists each product id and the missing fields.</p>\n<h2>Spec reference</h2>\n<p><code>source/schemas/shopping/types/product.json</code>, <code>variant.json</code>, <code>availability.json</code>.</p>\n",
  "markdown": "# Products include required fields\n\nSome products returned by search are missing fields the spec requires, or lack a product URL or variant availability that agents rely on.\n\n## How to fix\n\nRequired on each product: `id`, `title`, `description`, `price_range`, `variants`. Required on each variant: `id`, `title`, `description`, `price` (integer `amount` + `currency`). Strongly recommended: product `url` and variant `availability` (`{\"available\": true}`).\n\n## WooCommerce\n\nFill in product descriptions in WooCommerce (empty descriptions are common) and make sure each variation has a price.\n\n## How to verify\n\nRe-run the scan; evidence lists each product id and the missing fields.\n\n## Spec reference\n\n`source/schemas/shopping/types/product.json`, `variant.json`, `availability.json`.\n"
 },
 "catalog.search_responds": {
  "title": "Catalog search responds",
  "html": "<p>CartProbe sent a harmless catalog search (<code>POST &lt;endpoint&gt;/catalog/search</code> with a common word) and it failed. Agents use search to find products to recommend.</p>\n<h2>How to fix</h2>\n<ul>\n<li>Implement <code>POST /catalog/search</code> under your REST endpoint, accepting a JSON body like <code>{&quot;query&quot;: &quot;shoes&quot;}</code>.</li>\n<li>Requests from agents carry a <code>UCP-Agent</code> header with their profile URL; do not reject unknown agents outright for read-only search.</li>\n<li>Return HTTP 200 with a JSON body even when nothing matches (an empty <code>products</code> array).</li>\n</ul>\n<h2>WooCommerce</h2>\n<ul>\n<li>Confirm the plugin&#39;s catalog feature is enabled and the WooCommerce REST API works (<code>/wp-json/wc/v3/</code> should respond).</li>\n<li>Security plugins that block POST requests from non-browsers may need an allow rule for the UCP endpoint path.</li>\n</ul>\n<h2>How to verify</h2>\n<p>Run <code>curl -s -X POST &lt;endpoint&gt;/catalog/search -H &#39;content-type: application/json&#39; -H &#39;UCP-Agent: profile=&quot;https://example.com/.well-known/ucp&quot;&#39; -d &#39;{&quot;query&quot;:&quot;shirt&quot;}&#39;</code>.</p>\n<h2>Spec reference</h2>\n<p>UCP specification, <code>docs/specification/shopping/catalog/</code> (search.md, rest.md); REST binding <code>source/services/shopping/rest.openapi.json</code> operation <code>search_catalog</code>.</p>\n",
  "markdown": "# Catalog search responds\n\nCartProbe sent a harmless catalog search (`POST <endpoint>/catalog/search` with a common word) and it failed. Agents use search to find products to recommend.\n\n## How to fix\n\n- Implement `POST /catalog/search` under your REST endpoint, accepting a JSON body like `{\"query\": \"shoes\"}`.\n- Requests from agents carry a `UCP-Agent` header with their profile URL; do not reject unknown agents outright for read-only search.\n- Return HTTP 200 with a JSON body even when nothing matches (an empty `products` array).\n\n## WooCommerce\n\n- Confirm the plugin's catalog feature is enabled and the WooCommerce REST API works (`/wp-json/wc/v3/` should respond).\n- Security plugins that block POST requests from non-browsers may need an allow rule for the UCP endpoint path.\n\n## How to verify\n\nRun `curl -s -X POST <endpoint>/catalog/search -H 'content-type: application/json' -H 'UCP-Agent: profile=\"https://example.com/.well-known/ucp\"' -d '{\"query\":\"shirt\"}'`.\n\n## Spec reference\n\nUCP specification, `docs/specification/shopping/catalog/` (search.md, rest.md); REST binding `source/services/shopping/rest.openapi.json` operation `search_catalog`.\n"
 },
 "catalog.search_schema_valid": {
  "title": "Search response matches the UCP schema",
  "html": "<p>The search response does not match the catalog search response schema. Agents validate responses and may discard ones that fail.</p>\n<h2>How to fix</h2>\n<ul>\n<li>The response must have <code>ucp</code> (with <code>version</code>) and a <code>products</code> array.</li>\n<li>Each product needs <code>id</code>, <code>title</code>, <code>description</code> (e.g. <code>{&quot;plain&quot;: &quot;...&quot;}</code>), <code>price_range</code> (<code>min</code> and <code>max</code> prices) and <code>variants</code>.</li>\n<li>Prices are objects <code>{&quot;amount&quot;: &lt;integer minor units&gt;, &quot;currency&quot;: &quot;USD&quot;}</code>.</li>\n</ul>\n<h2>WooCommerce</h2>\n<p>Update the UCP plugin; schema mismatches usually mean the plugin targets an older spec version.</p>\n<h2>How to verify</h2>\n<p>Re-run the scan; each error lists the JSON path to fix.</p>\n<h2>Spec reference</h2>\n<p><code>source/schemas/shopping/catalog_search.json</code> (<code>$defs/search_response</code>) and <code>shopping/types/product.json</code>; UCP specification, <code>docs/specification/shopping/catalog/</code> (search.md, rest.md).</p>\n",
  "markdown": "# Search response matches the UCP schema\n\nThe search response does not match the catalog search response schema. Agents validate responses and may discard ones that fail.\n\n## How to fix\n\n- The response must have `ucp` (with `version`) and a `products` array.\n- Each product needs `id`, `title`, `description` (e.g. `{\"plain\": \"...\"}`), `price_range` (`min` and `max` prices) and `variants`.\n- Prices are objects `{\"amount\": <integer minor units>, \"currency\": \"USD\"}`.\n\n## WooCommerce\n\nUpdate the UCP plugin; schema mismatches usually mean the plugin targets an older spec version.\n\n## How to verify\n\nRe-run the scan; each error lists the JSON path to fix.\n\n## Spec reference\n\n`source/schemas/shopping/catalog_search.json` (`$defs/search_response`) and `shopping/types/product.json`; UCP specification, `docs/specification/shopping/catalog/` (search.md, rest.md).\n"
 },
 "checkout.capability_declared": {
  "title": "Checkout capability is declared",
  "html": "<p>Without <code>dev.ucp.shopping.checkout</code>, agents can recommend your products but cannot help a shopper buy them. For stores without verified ownership this result is informational and does not affect the score.</p>\n<h2>How to fix</h2>\n<p>Implement the checkout capability (create, get, update, complete, cancel checkout sessions) and declare it in your profile.</p>\n<h2>WooCommerce</h2>\n<p>Enable checkout in your UCP plugin and configure a supported payment handler.</p>\n<h2>How to verify</h2>\n<p>Look for <code>dev.ucp.shopping.checkout</code> under <code>ucp.capabilities</code>.</p>\n<h2>Spec reference</h2>\n<p>UCP specification, <code>docs/specification/shopping/checkout/</code> (index.md, rest.md).</p>\n",
  "markdown": "# Checkout capability is declared\n\nWithout `dev.ucp.shopping.checkout`, agents can recommend your products but cannot help a shopper buy them. For stores without verified ownership this result is informational and does not affect the score.\n\n## How to fix\n\nImplement the checkout capability (create, get, update, complete, cancel checkout sessions) and declare it in your profile.\n\n## WooCommerce\n\nEnable checkout in your UCP plugin and configure a supported payment handler.\n\n## How to verify\n\nLook for `dev.ucp.shopping.checkout` under `ucp.capabilities`.\n\n## Spec reference\n\nUCP specification, `docs/specification/shopping/checkout/` (index.md, rest.md).\n"
 },
 "checkout.session_cleanup": {
  "title": "Test checkout session is cancelled",
  "html": "<p>After creating the test session CartProbe immediately cancelled it with <code>POST /checkout-sessions/{id}/cancel</code>. The response should show <code>status: &quot;canceled&quot;</code> so no stock stays reserved.</p>\n<h2>How to fix</h2>\n<p>Implement the cancel operation and return the updated checkout with status <code>canceled</code>.</p>\n<h2>WooCommerce</h2>\n<p>Make sure the plugin releases held stock when a session is cancelled.</p>\n<h2>How to verify</h2>\n<p>Create and cancel a session manually against your test endpoint.</p>\n<h2>Spec reference</h2>\n<p>UCP specification, <code>docs/specification/shopping/checkout/</code> (index.md, rest.md), “Cancel Checkout”.</p>\n",
  "markdown": "# Test checkout session is cancelled\n\nAfter creating the test session CartProbe immediately cancelled it with `POST /checkout-sessions/{id}/cancel`. The response should show `status: \"canceled\"` so no stock stays reserved.\n\n## How to fix\n\nImplement the cancel operation and return the updated checkout with status `canceled`.\n\n## WooCommerce\n\nMake sure the plugin releases held stock when a session is cancelled.\n\n## How to verify\n\nCreate and cancel a session manually against your test endpoint.\n\n## Spec reference\n\nUCP specification, `docs/specification/shopping/checkout/` (index.md, rest.md), “Cancel Checkout”.\n"
 },
 "checkout.session_create": {
  "title": "Test checkout session can be created",
  "html": "<p>With your permission (verified ownership and a confirmed test-mode endpoint), CartProbe created a checkout session for one in-stock item and validated the response against the checkout schema. CartProbe never submits payment details and never completes a checkout.</p>\n<h2>How to fix</h2>\n<ul>\n<li><code>POST /checkout-sessions</code> with <code>{&quot;line_items&quot;:[{&quot;item&quot;:{&quot;id&quot;:&quot;...&quot;},&quot;quantity&quot;:1}]}</code> must return 200/201 with a checkout object: <code>ucp</code>, <code>id</code>, <code>line_items</code>, <code>status</code>, <code>currency</code>, <code>totals</code>, <code>links</code>.</li>\n<li>Fix the schema errors listed in the evidence.</li>\n</ul>\n<h2>WooCommerce</h2>\n<p>Point CartProbe at your plugin&#39;s test/sandbox endpoint and make sure the WooCommerce payment gateway is in test mode.</p>\n<h2>How to verify</h2>\n<p>Re-run the scan from your dashboard after fixing.</p>\n<h2>Spec reference</h2>\n<p>UCP specification, <code>docs/specification/shopping/checkout/</code> (index.md, rest.md); <code>source/schemas/shopping/checkout.json</code>.</p>\n",
  "markdown": "# Test checkout session can be created\n\nWith your permission (verified ownership and a confirmed test-mode endpoint), CartProbe created a checkout session for one in-stock item and validated the response against the checkout schema. CartProbe never submits payment details and never completes a checkout.\n\n## How to fix\n\n- `POST /checkout-sessions` with `{\"line_items\":[{\"item\":{\"id\":\"...\"},\"quantity\":1}]}` must return 200/201 with a checkout object: `ucp`, `id`, `line_items`, `status`, `currency`, `totals`, `links`.\n- Fix the schema errors listed in the evidence.\n\n## WooCommerce\n\nPoint CartProbe at your plugin's test/sandbox endpoint and make sure the WooCommerce payment gateway is in test mode.\n\n## How to verify\n\nRe-run the scan from your dashboard after fixing.\n\n## Spec reference\n\nUCP specification, `docs/specification/shopping/checkout/` (index.md, rest.md); `source/schemas/shopping/checkout.json`.\n"
 },
 "checkout.session_totals_integer": {
  "title": "Checkout totals are consistent integers",
  "html": "<p>Checkout <code>totals</code> must be integers in minor units, contain exactly one <code>subtotal</code> and one <code>total</code>, and all non-total entries must add up to the total. The spec says platforms must not autonomously complete a checkout whose totals do not add up.</p>\n<h2>How to fix</h2>\n<p>Compute totals with integer arithmetic in minor units; include every adjustment (tax, shipping, discounts as negative amounts) as its own entry.</p>\n<h2>WooCommerce</h2>\n<p>Rounding differences between WooCommerce&#39;s tax calculation and the plugin&#39;s conversion are a common cause; make the plugin convert the final WooCommerce totals rather than recomputing them.</p>\n<h2>How to verify</h2>\n<p>Check that <code>sum(amount for entries except total) == total</code>.</p>\n<h2>Spec reference</h2>\n<p>UCP specification, <code>docs/specification/shopping/checkout/</code> (index.md, rest.md), “Totals → Verification”; <code>source/schemas/common/types/totals.json</code>.</p>\n",
  "markdown": "# Checkout totals are consistent integers\n\nCheckout `totals` must be integers in minor units, contain exactly one `subtotal` and one `total`, and all non-total entries must add up to the total. The spec says platforms must not autonomously complete a checkout whose totals do not add up.\n\n## How to fix\n\nCompute totals with integer arithmetic in minor units; include every adjustment (tax, shipping, discounts as negative amounts) as its own entry.\n\n## WooCommerce\n\nRounding differences between WooCommerce's tax calculation and the plugin's conversion are a common cause; make the plugin convert the final WooCommerce totals rather than recomputing them.\n\n## How to verify\n\nCheck that `sum(amount for entries except total) == total`.\n\n## Spec reference\n\nUCP specification, `docs/specification/shopping/checkout/` (index.md, rest.md), “Totals → Verification”; `source/schemas/common/types/totals.json`.\n"
 },
 "consistency.availability_match": {
  "title": "Catalog availability matches product pages",
  "html": "<p>The catalog API and the product page disagree on whether an item is in stock. Agents may offer something shoppers cannot buy, or skip products that are available.</p>\n<h2>How to fix</h2>\n<p>Use one inventory source for both; when stock changes, invalidate both the API response cache and page cache.</p>\n<h2>WooCommerce</h2>\n<p>Enable WooCommerce stock management and make sure your page cache purges on stock changes (most cache plugins have a WooCommerce option for this).</p>\n<h2>How to verify</h2>\n<p>Compare <code>availability</code> in the page JSON-LD with <code>variants[].availability.available</code> in search results.</p>\n<h2>Spec reference</h2>\n<p>UCP specification, <code>docs/specification/shopping/catalog/</code> (search.md, rest.md); <code>source/schemas/shopping/types/availability.json</code>.</p>\n",
  "markdown": "# Catalog availability matches product pages\n\nThe catalog API and the product page disagree on whether an item is in stock. Agents may offer something shoppers cannot buy, or skip products that are available.\n\n## How to fix\n\nUse one inventory source for both; when stock changes, invalidate both the API response cache and page cache.\n\n## WooCommerce\n\nEnable WooCommerce stock management and make sure your page cache purges on stock changes (most cache plugins have a WooCommerce option for this).\n\n## How to verify\n\nCompare `availability` in the page JSON-LD with `variants[].availability.available` in search results.\n\n## Spec reference\n\nUCP specification, `docs/specification/shopping/catalog/` (search.md, rest.md); `source/schemas/shopping/types/availability.json`.\n"
 },
 "consistency.currency_match": {
  "title": "Catalog currency matches product pages",
  "html": "<p>The catalog uses a different currency than the product page for the same product.</p>\n<h2>How to fix</h2>\n<p>Report prices in the same currency in both places, or make sure the catalog honours the buyer&#39;s context consistently.</p>\n<h2>WooCommerce</h2>\n<p>Check multi-currency or geolocation plugins: CartProbe fetches pages without cookies from Cloudflare&#39;s network, so the default currency is used.</p>\n<h2>How to verify</h2>\n<p>Compare <code>priceCurrency</code> on the page with <code>price.currency</code> in search results.</p>\n<h2>Spec reference</h2>\n<p>UCP amounts: <code>source/schemas/common/types/amount.json</code> (integer minor units; no tolerance defined).</p>\n",
  "markdown": "# Catalog currency matches product pages\n\nThe catalog uses a different currency than the product page for the same product.\n\n## How to fix\n\nReport prices in the same currency in both places, or make sure the catalog honours the buyer's context consistently.\n\n## WooCommerce\n\nCheck multi-currency or geolocation plugins: CartProbe fetches pages without cookies from Cloudflare's network, so the default currency is used.\n\n## How to verify\n\nCompare `priceCurrency` on the page with `price.currency` in search results.\n\n## Spec reference\n\nUCP amounts: `source/schemas/common/types/amount.json` (integer minor units; no tolerance defined).\n"
 },
 "consistency.price_match": {
  "title": "Catalog prices match product pages",
  "html": "<p>For products that appear both in your catalog API and on your website, CartProbe converts both prices to minor units and compares them exactly. A mismatch means agents see one price and shoppers another.</p>\n<h2>How to fix</h2>\n<ul>\n<li>Make sure the UCP catalog and the product page read from the same price source, including sale prices and their schedule.</li>\n<li>Check currency conversion and tax display: if pages show tax-inclusive prices, the API should be consistent with how you charge.</li>\n<li>Clear caches after price changes (stale page cache is the most common cause).</li>\n</ul>\n<h2>WooCommerce</h2>\n<ul>\n<li>Sale prices: confirm the UCP plugin uses the active price (<code>get_price()</code>), not the regular price.</li>\n<li>Multi-currency plugins: make sure the API and the page use the same currency.</li>\n<li>Purge your page cache and CDN after bulk price edits.</li>\n</ul>\n<h2>How to verify</h2>\n<p>Re-run the scan after clearing caches; evidence lists each URL with both values.</p>\n<h2>Spec reference</h2>\n<p>UCP amounts: <code>source/schemas/common/types/amount.json</code> (integer minor units; no tolerance defined); UCP specification, <code>docs/specification/shopping/catalog/</code> (search.md, rest.md).</p>\n",
  "markdown": "# Catalog prices match product pages\n\nFor products that appear both in your catalog API and on your website, CartProbe converts both prices to minor units and compares them exactly. A mismatch means agents see one price and shoppers another.\n\n## How to fix\n\n- Make sure the UCP catalog and the product page read from the same price source, including sale prices and their schedule.\n- Check currency conversion and tax display: if pages show tax-inclusive prices, the API should be consistent with how you charge.\n- Clear caches after price changes (stale page cache is the most common cause).\n\n## WooCommerce\n\n- Sale prices: confirm the UCP plugin uses the active price (`get_price()`), not the regular price.\n- Multi-currency plugins: make sure the API and the page use the same currency.\n- Purge your page cache and CDN after bulk price edits.\n\n## How to verify\n\nRe-run the scan after clearing caches; evidence lists each URL with both values.\n\n## Spec reference\n\nUCP amounts: `source/schemas/common/types/amount.json` (integer minor units; no tolerance defined); UCP specification, `docs/specification/shopping/catalog/` (search.md, rest.md).\n"
 },
 "discovery.capabilities_declared": {
  "title": "Shopping capabilities are declared",
  "html": "<p>Your profile lists no shopping capabilities, so agents have nothing they can call on your store.</p>\n<h2>How to fix</h2>\n<p>Declare the capabilities you actually support under <code>ucp.capabilities</code>, for example:</p>\n<pre><code class=\"language-json\">&quot;dev.ucp.shopping.catalog.search&quot;: [{ &quot;version&quot;: &quot;2026-08-25&quot;, &quot;spec&quot;: &quot;https://ucp.dev/2026-08-25/specification/shopping/catalog/search&quot;, &quot;schema&quot;: &quot;https://ucp.dev/2026-08-25/schemas/shopping/catalog_search.json&quot; }],\n&quot;dev.ucp.shopping.checkout&quot;: [{ &quot;version&quot;: &quot;2026-08-25&quot;, &quot;spec&quot;: &quot;https://ucp.dev/2026-08-25/specification/shopping/checkout&quot;, &quot;schema&quot;: &quot;https://ucp.dev/2026-08-25/schemas/shopping/checkout.json&quot; }]\n</code></pre>\n<p>Only declare what your endpoints really implement.</p>\n<h2>WooCommerce</h2>\n<p>In your UCP plugin&#39;s settings, enable catalog search and checkout. Some plugins disable capabilities until WooCommerce REST API keys or payment settings are configured.</p>\n<h2>How to verify</h2>\n<p>The profile&#39;s <code>ucp.capabilities</code> object should list <code>dev.ucp.shopping.*</code> names.</p>\n<h2>Spec reference</h2>\n<p>UCP specification, <code>docs/specification/overview/index.md</code>, “Capabilities” and “Standard Capabilities”.</p>\n",
  "markdown": "# Shopping capabilities are declared\n\nYour profile lists no shopping capabilities, so agents have nothing they can call on your store.\n\n## How to fix\n\nDeclare the capabilities you actually support under `ucp.capabilities`, for example:\n\n```json\n\"dev.ucp.shopping.catalog.search\": [{ \"version\": \"2026-08-25\", \"spec\": \"https://ucp.dev/2026-08-25/specification/shopping/catalog/search\", \"schema\": \"https://ucp.dev/2026-08-25/schemas/shopping/catalog_search.json\" }],\n\"dev.ucp.shopping.checkout\": [{ \"version\": \"2026-08-25\", \"spec\": \"https://ucp.dev/2026-08-25/specification/shopping/checkout\", \"schema\": \"https://ucp.dev/2026-08-25/schemas/shopping/checkout.json\" }]\n```\n\nOnly declare what your endpoints really implement.\n\n## WooCommerce\n\nIn your UCP plugin's settings, enable catalog search and checkout. Some plugins disable capabilities until WooCommerce REST API keys or payment settings are configured.\n\n## How to verify\n\nThe profile's `ucp.capabilities` object should list `dev.ucp.shopping.*` names.\n\n## Spec reference\n\nUCP specification, `docs/specification/overview/index.md`, “Capabilities” and “Standard Capabilities”.\n"
 },
 "discovery.capability_versions_valid": {
  "title": "Capability versions are valid",
  "html": "<p>Each capability entry carries a <code>version</code>. Agents negotiate by exact version match, so a malformed or unknown version means the capability is never activated.</p>\n<h2>How to fix</h2>\n<ul>\n<li>Use the <code>YYYY-MM-DD</code> format.</li>\n<li>For <code>dev.ucp.*</code> capabilities, use the UCP release date your implementation follows; in a profile for release D, those entries declare version D.</li>\n<li>Third-party (<code>com.vendor.*</code>) extensions use their author&#39;s version and only need the right format.</li>\n</ul>\n<h2>WooCommerce</h2>\n<p>Update the UCP plugin; if versions are configurable, set them to the release your plugin implements.</p>\n<h2>How to verify</h2>\n<p>Each <code>version</code> value in <code>ucp.capabilities</code> should look like <code>2026-08-25</code>.</p>\n<h2>Spec reference</h2>\n<p>UCP specification, <code>docs/specification/overview/index.md</code>, “Versioning → Capability Versions”.</p>\n",
  "markdown": "# Capability versions are valid\n\nEach capability entry carries a `version`. Agents negotiate by exact version match, so a malformed or unknown version means the capability is never activated.\n\n## How to fix\n\n- Use the `YYYY-MM-DD` format.\n- For `dev.ucp.*` capabilities, use the UCP release date your implementation follows; in a profile for release D, those entries declare version D.\n- Third-party (`com.vendor.*`) extensions use their author's version and only need the right format.\n\n## WooCommerce\n\nUpdate the UCP plugin; if versions are configurable, set them to the release your plugin implements.\n\n## How to verify\n\nEach `version` value in `ucp.capabilities` should look like `2026-08-25`.\n\n## Spec reference\n\nUCP specification, `docs/specification/overview/index.md`, “Versioning → Capability Versions”.\n"
 },
 "discovery.endpoints_reachable": {
  "title": "Declared service endpoints respond",
  "html": "<p>Your profile declares service endpoints (REST, MCP or A2A) that returned a server error or did not respond. CartProbe sends only a plain GET with no side effects; any response below 500 counts as alive.</p>\n<h2>How to fix</h2>\n<ul>\n<li>Check the <code>endpoint</code> URLs under <code>ucp.services</code> are correct and publicly reachable over HTTPS.</li>\n<li>Look at server logs for 5xx errors on those paths.</li>\n<li>Endpoints should not have a trailing slash; OpenAPI paths are appended directly.</li>\n</ul>\n<h2>WooCommerce</h2>\n<ul>\n<li>Make sure the WordPress REST API is enabled (some security plugins disable it for logged-out users).</li>\n<li>Re-save permalinks after installing the UCP plugin.</li>\n</ul>\n<h2>How to verify</h2>\n<p><code>curl -s -o /dev/null -w &#39;%{http_code}&#39; &lt;endpoint&gt;</code> should print a status below 500.</p>\n<h2>Spec reference</h2>\n<p>UCP specification, <code>docs/specification/overview/index.md</code>, “Services → Endpoint Resolution”.</p>\n",
  "markdown": "# Declared service endpoints respond\n\nYour profile declares service endpoints (REST, MCP or A2A) that returned a server error or did not respond. CartProbe sends only a plain GET with no side effects; any response below 500 counts as alive.\n\n## How to fix\n\n- Check the `endpoint` URLs under `ucp.services` are correct and publicly reachable over HTTPS.\n- Look at server logs for 5xx errors on those paths.\n- Endpoints should not have a trailing slash; OpenAPI paths are appended directly.\n\n## WooCommerce\n\n- Make sure the WordPress REST API is enabled (some security plugins disable it for logged-out users).\n- Re-save permalinks after installing the UCP plugin.\n\n## How to verify\n\n`curl -s -o /dev/null -w '%{http_code}' <endpoint>` should print a status below 500.\n\n## Spec reference\n\nUCP specification, `docs/specification/overview/index.md`, “Services → Endpoint Resolution”.\n"
 },
 "discovery.mcp_transport_declared": {
  "title": "Additional transports (MCP / A2A)",
  "html": "<p>Informational. Besides REST, UCP services can be offered over MCP (Model Context Protocol) and A2A (Agent-to-Agent). Some assistants prefer these. This check never lowers your score.</p>\n<h2>How to fix</h2>\n<p>If your platform supports it, add an <code>mcp</code> (and/or <code>a2a</code>) binding to the <code>dev.ucp.shopping</code> service with its <code>endpoint</code>.</p>\n<h2>WooCommerce</h2>\n<p>Check whether your UCP plugin offers an MCP endpoint and enable it.</p>\n<h2>How to verify</h2>\n<p>The <code>ucp.services.dev.ucp.shopping</code> array lists entries with <code>transport</code> <code>mcp</code> or <code>a2a</code>.</p>\n<h2>Spec reference</h2>\n<p>UCP specification, <code>docs/specification/overview/index.md</code>, “Transport Layer”.</p>\n",
  "markdown": "# Additional transports (MCP / A2A)\n\nInformational. Besides REST, UCP services can be offered over MCP (Model Context Protocol) and A2A (Agent-to-Agent). Some assistants prefer these. This check never lowers your score.\n\n## How to fix\n\nIf your platform supports it, add an `mcp` (and/or `a2a`) binding to the `dev.ucp.shopping` service with its `endpoint`.\n\n## WooCommerce\n\nCheck whether your UCP plugin offers an MCP endpoint and enable it.\n\n## How to verify\n\nThe `ucp.services.dev.ucp.shopping` array lists entries with `transport` `mcp` or `a2a`.\n\n## Spec reference\n\nUCP specification, `docs/specification/overview/index.md`, “Transport Layer”.\n"
 },
 "discovery.namespace_host_rule": {
  "title": "Schema URLs match capability namespaces",
  "html": "<p>UCP binds each capability name to the domain that serves its schema. The <code>schema</code> URL host, with its labels reversed, must equal the name or be a label-aligned prefix of it: <code>dev.ucp.shopping.checkout</code> must use a schema on <code>ucp.dev</code>. Agents must ignore entities whose schema URL fails this rule.</p>\n<h2>How to fix</h2>\n<ul>\n<li>For <code>dev.ucp.*</code> capabilities, point <code>schema</code> at <code>https://ucp.dev/&lt;version&gt;/schemas/...</code>, not at a copy on your CDN or plugin host.</li>\n<li>For your own extensions, use your own namespace (<code>com.yourcompany.*</code>) and serve the schema from <code>yourcompany.com</code>.</li>\n<li>The URL must be https and must not contain <code>user@</code> tricks.</li>\n</ul>\n<h2>WooCommerce</h2>\n<p>If your UCP plugin rewrites schema URLs to a local copy, look for a setting to use the canonical ucp.dev URLs, or report it to the plugin author.</p>\n<h2>How to verify</h2>\n<p>For each capability, reverse the schema host labels (<code>ucp.dev</code> → <code>dev.ucp</code>) and check the capability name starts with it followed by a dot.</p>\n<h2>Spec reference</h2>\n<p>UCP specification, <code>docs/specification/overview/index.md</code>, “Namespace Governance → Authority Binding → Derivation algorithm”.</p>\n",
  "markdown": "# Schema URLs match capability namespaces\n\nUCP binds each capability name to the domain that serves its schema. The `schema` URL host, with its labels reversed, must equal the name or be a label-aligned prefix of it: `dev.ucp.shopping.checkout` must use a schema on `ucp.dev`. Agents must ignore entities whose schema URL fails this rule.\n\n## How to fix\n\n- For `dev.ucp.*` capabilities, point `schema` at `https://ucp.dev/<version>/schemas/...`, not at a copy on your CDN or plugin host.\n- For your own extensions, use your own namespace (`com.yourcompany.*`) and serve the schema from `yourcompany.com`.\n- The URL must be https and must not contain `user@` tricks.\n\n## WooCommerce\n\nIf your UCP plugin rewrites schema URLs to a local copy, look for a setting to use the canonical ucp.dev URLs, or report it to the plugin author.\n\n## How to verify\n\nFor each capability, reverse the schema host labels (`ucp.dev` → `dev.ucp`) and check the capability name starts with it followed by a dot.\n\n## Spec reference\n\nUCP specification, `docs/specification/overview/index.md`, “Namespace Governance → Authority Binding → Derivation algorithm”.\n"
 },
 "discovery.profile_cache_headers": {
  "title": "Profile is cacheable",
  "html": "<p>The spec requires published profiles to send <code>Cache-Control</code> with <code>public</code> and a <code>max-age</code> of at least 60 seconds, and forbids <code>private</code>, <code>no-store</code> and <code>no-cache</code>. It also recommends an <code>ETag</code> or <code>Last-Modified</code> header.</p>\n<h2>How to fix</h2>\n<p>Send for example <code>Cache-Control: public, max-age=300</code> and an <code>ETag</code> on <code>/.well-known/ucp</code>.</p>\n<h2>WooCommerce</h2>\n<ul>\n<li>WordPress often adds <code>no-cache</code> headers for dynamic routes. Your UCP plugin may need a setting, or add a header rule in your web server or CDN for this path.</li>\n<li>Cloudflare: a Cache Rule for <code>/.well-known/ucp</code> with an edge TTL plus a Transform Rule that sets <code>Cache-Control</code>.</li>\n</ul>\n<h2>How to verify</h2>\n<p><code>curl -sI https://&lt;your-domain&gt;/.well-known/ucp | grep -iE &#39;cache-control|etag|last-modified&#39;</code>.</p>\n<h2>Spec reference</h2>\n<p>UCP specification, <code>docs/specification/overview/index.md</code>, “Profile Requirements → Hosting” (items 3 and 4).</p>\n",
  "markdown": "# Profile is cacheable\n\nThe spec requires published profiles to send `Cache-Control` with `public` and a `max-age` of at least 60 seconds, and forbids `private`, `no-store` and `no-cache`. It also recommends an `ETag` or `Last-Modified` header.\n\n## How to fix\n\nSend for example `Cache-Control: public, max-age=300` and an `ETag` on `/.well-known/ucp`.\n\n## WooCommerce\n\n- WordPress often adds `no-cache` headers for dynamic routes. Your UCP plugin may need a setting, or add a header rule in your web server or CDN for this path.\n- Cloudflare: a Cache Rule for `/.well-known/ucp` with an edge TTL plus a Transform Rule that sets `Cache-Control`.\n\n## How to verify\n\n`curl -sI https://<your-domain>/.well-known/ucp | grep -iE 'cache-control|etag|last-modified'`.\n\n## Spec reference\n\nUCP specification, `docs/specification/overview/index.md`, “Profile Requirements → Hosting” (items 3 and 4).\n"
 },
 "discovery.profile_content_type": {
  "title": "Profile is served as JSON",
  "html": "<p>Your profile body should be sent with a JSON <code>Content-Type</code> header. Some clients refuse to parse a body declared as <code>text/html</code> or <code>text/plain</code>.</p>\n<h2>How to fix</h2>\n<p>Set the response header <code>Content-Type: application/json</code> for <code>/.well-known/ucp</code>.</p>\n<h2>WooCommerce</h2>\n<ul>\n<li>Most UCP plugins set the header automatically. If you see <code>text/html</code>, a caching or optimisation plugin may be rewriting the response: exclude <code>/.well-known/ucp</code> from page caching and HTML minification.</li>\n<li>On Nginx you can add <code>location = /.well-known/ucp { default_type application/json; }</code>.</li>\n</ul>\n<h2>How to verify</h2>\n<p><code>curl -sI https://&lt;your-domain&gt;/.well-known/ucp | grep -i content-type</code> should print <code>application/json</code>.</p>\n<h2>Spec reference</h2>\n<p>UCP specification, <code>docs/specification/overview/index.md</code>, “Profile Structure”.</p>\n",
  "markdown": "# Profile is served as JSON\n\nYour profile body should be sent with a JSON `Content-Type` header. Some clients refuse to parse a body declared as `text/html` or `text/plain`.\n\n## How to fix\n\nSet the response header `Content-Type: application/json` for `/.well-known/ucp`.\n\n## WooCommerce\n\n- Most UCP plugins set the header automatically. If you see `text/html`, a caching or optimisation plugin may be rewriting the response: exclude `/.well-known/ucp` from page caching and HTML minification.\n- On Nginx you can add `location = /.well-known/ucp { default_type application/json; }`.\n\n## How to verify\n\n`curl -sI https://<your-domain>/.well-known/ucp | grep -i content-type` should print `application/json`.\n\n## Spec reference\n\nUCP specification, `docs/specification/overview/index.md`, “Profile Structure”.\n"
 },
 "discovery.profile_latency": {
  "title": "Profile responds quickly",
  "html": "<p>Your profile took long to start responding. Agents fetch it at the start of a conversation and may give up on slow stores.</p>\n<h2>How to fix</h2>\n<ul>\n<li>Serve the profile from cache (it changes rarely): a CDN edge cache or a static file is ideal.</li>\n<li>The spec already requires <code>Cache-Control: public, max-age</code> of at least 60 seconds, which lets CDNs cache it.</li>\n</ul>\n<h2>WooCommerce</h2>\n<p>Use a page cache or CDN that caches <code>/.well-known/ucp</code>; avoid generating the profile with heavy database queries on each request.</p>\n<h2>How to verify</h2>\n<p><code>curl -s -o /dev/null -w &#39;%{time_starttransfer}\\n&#39; https://&lt;your-domain&gt;/.well-known/ucp</code> should be under 0.8 seconds.</p>\n<h2>Spec reference</h2>\n<p>UCP specification, <code>docs/specification/overview/index.md</code>, “Profile Requirements → Hosting”.</p>\n",
  "markdown": "# Profile responds quickly\n\nYour profile took long to start responding. Agents fetch it at the start of a conversation and may give up on slow stores.\n\n## How to fix\n\n- Serve the profile from cache (it changes rarely): a CDN edge cache or a static file is ideal.\n- The spec already requires `Cache-Control: public, max-age` of at least 60 seconds, which lets CDNs cache it.\n\n## WooCommerce\n\nUse a page cache or CDN that caches `/.well-known/ucp`; avoid generating the profile with heavy database queries on each request.\n\n## How to verify\n\n`curl -s -o /dev/null -w '%{time_starttransfer}\\n' https://<your-domain>/.well-known/ucp` should be under 0.8 seconds.\n\n## Spec reference\n\nUCP specification, `docs/specification/overview/index.md`, “Profile Requirements → Hosting”.\n"
 },
 "discovery.profile_parses": {
  "title": "Profile is valid JSON",
  "html": "<p>The profile body could not be parsed as a JSON object. A stray PHP warning, an HTML error page, or a trailing comma is enough to break it.</p>\n<h2>How to fix</h2>\n<ul>\n<li>Fetch the URL and paste the body into a JSON validator to find the exact error.</li>\n<li>Remove anything printed before the JSON (debug output, BOM characters, PHP notices).</li>\n<li>The top level must be an object with a <code>ucp</code> member.</li>\n</ul>\n<h2>WooCommerce</h2>\n<ul>\n<li>Turn off <code>WP_DEBUG_DISPLAY</code> on production so PHP notices are not printed into responses.</li>\n<li>Update the UCP plugin; if the problem started after an update, check the plugin&#39;s support forum.</li>\n</ul>\n<h2>How to verify</h2>\n<p><code>curl -s https://&lt;your-domain&gt;/.well-known/ucp | python3 -m json.tool</code> should pretty-print without an error.</p>\n<h2>Spec reference</h2>\n<p>UCP specification, <code>docs/specification/overview/index.md</code>, “Profile Structure”.</p>\n",
  "markdown": "# Profile is valid JSON\n\nThe profile body could not be parsed as a JSON object. A stray PHP warning, an HTML error page, or a trailing comma is enough to break it.\n\n## How to fix\n\n- Fetch the URL and paste the body into a JSON validator to find the exact error.\n- Remove anything printed before the JSON (debug output, BOM characters, PHP notices).\n- The top level must be an object with a `ucp` member.\n\n## WooCommerce\n\n- Turn off `WP_DEBUG_DISPLAY` on production so PHP notices are not printed into responses.\n- Update the UCP plugin; if the problem started after an update, check the plugin's support forum.\n\n## How to verify\n\n`curl -s https://<your-domain>/.well-known/ucp | python3 -m json.tool` should pretty-print without an error.\n\n## Spec reference\n\nUCP specification, `docs/specification/overview/index.md`, “Profile Structure”.\n"
 },
 "discovery.profile_reachable": {
  "title": "UCP profile is reachable",
  "html": "<p>AI shopping agents discover your store by requesting <code>https://&lt;your-domain&gt;/.well-known/ucp</code>. If that URL returns an error, times out, or redirects, agents treat your store as not supporting UCP.</p>\n<h2>How to fix</h2>\n<ul>\n<li>Publish a JSON business profile at exactly <code>/.well-known/ucp</code> on your store&#39;s main domain, served over HTTPS with status 200.</li>\n<li>Do <strong>not</strong> redirect this URL (no 301/302 to <code>www.</code> or to a trailing-slash version). The spec says profile endpoints must not use redirects and agents must not follow them. Serve it on the exact host shoppers use.</li>\n<li>Make sure firewalls, bot protection or &quot;maintenance mode&quot; plugins do not block <code>/.well-known/</code> paths.</li>\n</ul>\n<h2>WooCommerce</h2>\n<ul>\n<li>Install and activate a UCP plugin (for example &quot;UCP Ready&quot; or &quot;WebToffee Universal Commerce Protocol Enabler&quot;), then re-save your permalinks (Settings → Permalinks → Save) so WordPress registers the <code>/.well-known/ucp</code> route.</li>\n<li>If you use Cloudflare or a security plugin (Wordfence, iThemes), allow requests to <code>/.well-known/ucp</code>.</li>\n<li>If your site redirects between <code>www</code> and the bare domain, scan the domain you actually serve and make sure the profile is served there without a redirect.</li>\n</ul>\n<h2>How to verify</h2>\n<p>Open <code>https://&lt;your-domain&gt;/.well-known/ucp</code> in a private browser window: you should see JSON, and the address bar must not change. Or run <code>curl -sI https://&lt;your-domain&gt;/.well-known/ucp</code> and check for <code>HTTP/2 200</code> with no <code>location:</code> header.</p>\n<h2>Spec reference</h2>\n<p>UCP specification, <code>docs/specification/overview/index.md</code>, sections “Profile Structure → Business Profile” and “Profile Requirements → Hosting”.</p>\n",
  "markdown": "# UCP profile is reachable\n\nAI shopping agents discover your store by requesting `https://<your-domain>/.well-known/ucp`. If that URL returns an error, times out, or redirects, agents treat your store as not supporting UCP.\n\n## How to fix\n\n- Publish a JSON business profile at exactly `/.well-known/ucp` on your store's main domain, served over HTTPS with status 200.\n- Do **not** redirect this URL (no 301/302 to `www.` or to a trailing-slash version). The spec says profile endpoints must not use redirects and agents must not follow them. Serve it on the exact host shoppers use.\n- Make sure firewalls, bot protection or \"maintenance mode\" plugins do not block `/.well-known/` paths.\n\n## WooCommerce\n\n- Install and activate a UCP plugin (for example \"UCP Ready\" or \"WebToffee Universal Commerce Protocol Enabler\"), then re-save your permalinks (Settings → Permalinks → Save) so WordPress registers the `/.well-known/ucp` route.\n- If you use Cloudflare or a security plugin (Wordfence, iThemes), allow requests to `/.well-known/ucp`.\n- If your site redirects between `www` and the bare domain, scan the domain you actually serve and make sure the profile is served there without a redirect.\n\n## How to verify\n\nOpen `https://<your-domain>/.well-known/ucp` in a private browser window: you should see JSON, and the address bar must not change. Or run `curl -sI https://<your-domain>/.well-known/ucp` and check for `HTTP/2 200` with no `location:` header.\n\n## Spec reference\n\nUCP specification, `docs/specification/overview/index.md`, sections “Profile Structure → Business Profile” and “Profile Requirements → Hosting”.\n"
 },
 "discovery.profile_schema_valid": {
  "title": "Profile matches the UCP schema",
  "html": "<p>Your profile is JSON but does not match the published UCP business profile schema for the version it declares. Each listed error shows the JSON path that is wrong and the schema rule it breaks.</p>\n<h2>How to fix</h2>\n<ul>\n<li>Work through the errors from the top; one structural problem (for example a missing <code>payment_handlers</code> object) often causes several messages.</li>\n<li>Required at <code>ucp</code>: <code>version</code>, <code>services</code> and <code>payment_handlers</code> (both registries must exist even when empty, e.g. <code>&quot;payment_handlers&quot;: {}</code>).</li>\n<li>Each service entry needs <code>version</code> and a <code>transport</code> of <code>rest</code>, <code>mcp</code>, <code>a2a</code> or <code>embedded</code>; REST/MCP/A2A bindings need an <code>endpoint</code>.</li>\n<li>Each capability entry needs <code>version</code> and a <code>schema</code> URL.</li>\n</ul>\n<h2>WooCommerce</h2>\n<p>Update your UCP plugin to its latest release; most schema errors come from plugins written against an older spec version. If the plugin lets you edit the profile manually, fix the fields named in the errors.</p>\n<h2>How to verify</h2>\n<p>Re-run the CartProbe scan. You can also validate locally with the UCP <code>ucp-schema</code> tool from the specification repository.</p>\n<h2>Spec reference</h2>\n<p>Schemas: <code>source/schemas/profile.json</code> (<code>$defs/business_schema</code>), <code>ucp.json</code>, <code>service.json</code>, <code>capability.json</code> in the UCP repository; UCP specification, <code>docs/specification/overview/index.md</code>, “Profile Structure”.</p>\n",
  "markdown": "# Profile matches the UCP schema\n\nYour profile is JSON but does not match the published UCP business profile schema for the version it declares. Each listed error shows the JSON path that is wrong and the schema rule it breaks.\n\n## How to fix\n\n- Work through the errors from the top; one structural problem (for example a missing `payment_handlers` object) often causes several messages.\n- Required at `ucp`: `version`, `services` and `payment_handlers` (both registries must exist even when empty, e.g. `\"payment_handlers\": {}`).\n- Each service entry needs `version` and a `transport` of `rest`, `mcp`, `a2a` or `embedded`; REST/MCP/A2A bindings need an `endpoint`.\n- Each capability entry needs `version` and a `schema` URL.\n\n## WooCommerce\n\nUpdate your UCP plugin to its latest release; most schema errors come from plugins written against an older spec version. If the plugin lets you edit the profile manually, fix the fields named in the errors.\n\n## How to verify\n\nRe-run the CartProbe scan. You can also validate locally with the UCP `ucp-schema` tool from the specification repository.\n\n## Spec reference\n\nSchemas: `source/schemas/profile.json` (`$defs/business_schema`), `ucp.json`, `service.json`, `capability.json` in the UCP repository; UCP specification, `docs/specification/overview/index.md`, “Profile Structure”.\n"
 },
 "discovery.version_current": {
  "title": "Profile uses the current UCP version",
  "html": "<p><code>ucp.version</code> in your profile is not the latest published UCP release. Agents prefer the newest version both sides support; staying behind means newer features (and eventually older-version support) are lost.</p>\n<h2>How to fix</h2>\n<ul>\n<li>Upgrade your UCP implementation to the latest release and set <code>ucp.version</code> to it.</li>\n<li>If you must keep supporting an older version, keep the newest version at <code>/.well-known/ucp</code> and list older ones in <code>ucp.supported_versions</code>, each pointing to a complete profile for that version.</li>\n<li><code>ucp.version</code> must be a dated release (<code>YYYY-MM-DD</code>); values like <code>&quot;draft&quot;</code> must never be published.</li>\n</ul>\n<h2>WooCommerce</h2>\n<p>Update the UCP plugin. After updating, clear any page cache so the new profile is served.</p>\n<h2>How to verify</h2>\n<p>Check <code>ucp.version</code> at <code>https://&lt;your-domain&gt;/.well-known/ucp</code> and compare with the latest release listed on ucp.dev.</p>\n<h2>Spec reference</h2>\n<p>UCP specification, <code>docs/specification/overview/index.md</code>, “Versioning → Protocol Version” and “Pre-release Versions”.</p>\n",
  "markdown": "# Profile uses the current UCP version\n\n`ucp.version` in your profile is not the latest published UCP release. Agents prefer the newest version both sides support; staying behind means newer features (and eventually older-version support) are lost.\n\n## How to fix\n\n- Upgrade your UCP implementation to the latest release and set `ucp.version` to it.\n- If you must keep supporting an older version, keep the newest version at `/.well-known/ucp` and list older ones in `ucp.supported_versions`, each pointing to a complete profile for that version.\n- `ucp.version` must be a dated release (`YYYY-MM-DD`); values like `\"draft\"` must never be published.\n\n## WooCommerce\n\nUpdate the UCP plugin. After updating, clear any page cache so the new profile is served.\n\n## How to verify\n\nCheck `ucp.version` at `https://<your-domain>/.well-known/ucp` and compare with the latest release listed on ucp.dev.\n\n## Spec reference\n\nUCP specification, `docs/specification/overview/index.md`, “Versioning → Protocol Version” and “Pre-release Versions”.\n"
 },
 "products.availability": {
  "title": "Products state availability",
  "html": "<p><code>offers.availability</code> should use a schema.org ItemAvailability URL such as <code>https://schema.org/InStock</code> or <code>https://schema.org/OutOfStock</code>. Bare words like <code>InStock</code> or <code>in stock</code> are not reliably understood.</p>\n<h2>How to fix</h2>\n<p>Output the full URL form, e.g. <code>&quot;availability&quot;: &quot;https://schema.org/InStock&quot;</code>.</p>\n<h2>WooCommerce</h2>\n<p>Enable stock management in WooCommerce → Settings → Products → Inventory so availability is accurate; SEO plugins output the URL form.</p>\n<h2>How to verify</h2>\n<p>Look for <code>&quot;availability&quot;: &quot;https://schema.org/...&quot;</code> in the page source.</p>\n<h2>Spec reference</h2>\n<p>schema.org <code>ItemAvailability</code>.</p>\n",
  "markdown": "# Products state availability\n\n`offers.availability` should use a schema.org ItemAvailability URL such as `https://schema.org/InStock` or `https://schema.org/OutOfStock`. Bare words like `InStock` or `in stock` are not reliably understood.\n\n## How to fix\n\nOutput the full URL form, e.g. `\"availability\": \"https://schema.org/InStock\"`.\n\n## WooCommerce\n\nEnable stock management in WooCommerce → Settings → Products → Inventory so availability is accurate; SEO plugins output the URL form.\n\n## How to verify\n\nLook for `\"availability\": \"https://schema.org/...\"` in the page source.\n\n## Spec reference\n\nschema.org `ItemAvailability`.\n"
 },
 "products.core_fields": {
  "title": "Products have name, image and price",
  "html": "<p>The basic fields an agent needs to present a product are missing on some pages: <code>name</code>, <code>image</code>, <code>offers.price</code> (or <code>lowPrice</code> for a range) and <code>offers.priceCurrency</code>.</p>\n<h2>How to fix</h2>\n<p>Make sure every Product has all four. For variable products use <code>ProductGroup</code> with <code>hasVariant</code>, or an <code>AggregateOffer</code> with <code>lowPrice</code>/<code>highPrice</code>.</p>\n<h2>WooCommerce</h2>\n<p>Set a featured image and a price on every product and variation; WooCommerce omits <code>offers</code> when a product has no price.</p>\n<h2>How to verify</h2>\n<p>Validate a few product URLs in the Rich Results Test.</p>\n<h2>Spec reference</h2>\n<p>Google Search Central “Product structured data” and schema.org <code>Product</code>/<code>Offer</code>.</p>\n",
  "markdown": "# Products have name, image and price\n\nThe basic fields an agent needs to present a product are missing on some pages: `name`, `image`, `offers.price` (or `lowPrice` for a range) and `offers.priceCurrency`.\n\n## How to fix\n\nMake sure every Product has all four. For variable products use `ProductGroup` with `hasVariant`, or an `AggregateOffer` with `lowPrice`/`highPrice`.\n\n## WooCommerce\n\nSet a featured image and a price on every product and variation; WooCommerce omits `offers` when a product has no price.\n\n## How to verify\n\nValidate a few product URLs in the Rich Results Test.\n\n## Spec reference\n\nGoogle Search Central “Product structured data” and schema.org `Product`/`Offer`.\n"
 },
 "products.identifiers": {
  "title": "Products have brand and identifiers",
  "html": "<p>Brand plus a global identifier (GTIN/EAN/UPC or MPN) or at least a SKU lets agents match your product to what the shopper asked for and compare offers.</p>\n<h2>How to fix</h2>\n<p>Add <code>brand</code> (<code>{&quot;@type&quot;:&quot;Brand&quot;,&quot;name&quot;:&quot;...&quot;}</code>) and <code>gtin13</code>/<code>gtin</code>/<code>mpn</code>/<code>sku</code> to Product markup.</p>\n<h2>WooCommerce</h2>\n<ul>\n<li>WooCommerce has a built-in “GTIN, UPC, EAN, or ISBN” field (since 9.2) under Inventory; fill it in.</li>\n<li>Brands: use WooCommerce Brands, and make sure your SEO plugin maps it to <code>brand</code>.</li>\n</ul>\n<h2>How to verify</h2>\n<p>Check the JSON-LD contains <code>brand</code> and one identifier.</p>\n<h2>Spec reference</h2>\n<p>Google Search Central “Product structured data” and schema.org <code>Product</code>/<code>Offer</code>.</p>\n",
  "markdown": "# Products have brand and identifiers\n\nBrand plus a global identifier (GTIN/EAN/UPC or MPN) or at least a SKU lets agents match your product to what the shopper asked for and compare offers.\n\n## How to fix\n\nAdd `brand` (`{\"@type\":\"Brand\",\"name\":\"...\"}`) and `gtin13`/`gtin`/`mpn`/`sku` to Product markup.\n\n## WooCommerce\n\n- WooCommerce has a built-in “GTIN, UPC, EAN, or ISBN” field (since 9.2) under Inventory; fill it in.\n- Brands: use WooCommerce Brands, and make sure your SEO plugin maps it to `brand`.\n\n## How to verify\n\nCheck the JSON-LD contains `brand` and one identifier.\n\n## Spec reference\n\nGoogle Search Central “Product structured data” and schema.org `Product`/`Offer`.\n"
 },
 "products.jsonld_present": {
  "title": "Product pages have structured data",
  "html": "<p>Product pages should include schema.org <code>Product</code> (or <code>ProductGroup</code> for variants) as JSON-LD. Agents and shopping surfaces read it to understand what a page sells.</p>\n<h2>How to fix</h2>\n<p>Add a <code>&lt;script type=&quot;application/ld+json&quot;&gt;</code> block with a <code>Product</code> (name, image, offers…) to every product page.</p>\n<h2>WooCommerce</h2>\n<ul>\n<li>WooCommerce outputs basic Product JSON-LD by default; it can be removed by themes or page builders. SEO plugins (Yoast WooCommerce SEO, Rank Math) output richer markup.</li>\n<li>Check your theme does not dequeue WooCommerce structured data.</li>\n</ul>\n<h2>How to verify</h2>\n<p>Paste a product URL into Google&#39;s Rich Results Test or Schema.org validator.</p>\n<h2>Spec reference</h2>\n<p>Google Search Central “Product structured data” and schema.org <code>Product</code>/<code>Offer</code>.</p>\n",
  "markdown": "# Product pages have structured data\n\nProduct pages should include schema.org `Product` (or `ProductGroup` for variants) as JSON-LD. Agents and shopping surfaces read it to understand what a page sells.\n\n## How to fix\n\nAdd a `<script type=\"application/ld+json\">` block with a `Product` (name, image, offers…) to every product page.\n\n## WooCommerce\n\n- WooCommerce outputs basic Product JSON-LD by default; it can be removed by themes or page builders. SEO plugins (Yoast WooCommerce SEO, Rank Math) output richer markup.\n- Check your theme does not dequeue WooCommerce structured data.\n\n## How to verify\n\nPaste a product URL into Google's Rich Results Test or Schema.org validator.\n\n## Spec reference\n\nGoogle Search Central “Product structured data” and schema.org `Product`/`Offer`.\n"
 },
 "products.price_format": {
  "title": "Prices are machine-readable",
  "html": "<p>Structured-data prices must be plain decimals with a dot (<code>1299.00</code>): no currency symbols, thousands separators or HTML, and no more decimal places than the currency uses.</p>\n<h2>How to fix</h2>\n<p>Output <code>&quot;price&quot;: &quot;1299.00&quot;</code> and put the currency in <code>priceCurrency</code>.</p>\n<h2>WooCommerce</h2>\n<p>Check WooCommerce → Settings → General currency options; some themes print formatted prices (<code>$1,299.00</code>) into JSON-LD. Prefer the structured data from WooCommerce or your SEO plugin.</p>\n<h2>How to verify</h2>\n<p>In page source, <code>price</code> should look like <code>19.99</code>.</p>\n<h2>Spec reference</h2>\n<p>Google Search Central “Product structured data” and schema.org <code>Product</code>/<code>Offer</code>.</p>\n",
  "markdown": "# Prices are machine-readable\n\nStructured-data prices must be plain decimals with a dot (`1299.00`): no currency symbols, thousands separators or HTML, and no more decimal places than the currency uses.\n\n## How to fix\n\nOutput `\"price\": \"1299.00\"` and put the currency in `priceCurrency`.\n\n## WooCommerce\n\nCheck WooCommerce → Settings → General currency options; some themes print formatted prices (`$1,299.00`) into JSON-LD. Prefer the structured data from WooCommerce or your SEO plugin.\n\n## How to verify\n\nIn page source, `price` should look like `19.99`.\n\n## Spec reference\n\nGoogle Search Central “Product structured data” and schema.org `Product`/`Offer`.\n"
 },
 "products.return_policy": {
  "title": "Return policy is declared",
  "html": "<p><code>hasMerchantReturnPolicy</code> on the offer, or on your Organization, lets agents tell shoppers how returns work.</p>\n<h2>How to fix</h2>\n<p>Add a <code>MerchantReturnPolicy</code> (applicable country, return window, method, fees) once on your Organization markup, or on each Offer.</p>\n<h2>WooCommerce</h2>\n<p>Use your SEO plugin&#39;s organization/return policy settings; otherwise add Organization JSON-LD with <code>hasMerchantReturnPolicy</code> site-wide.</p>\n<h2>How to verify</h2>\n<p>Validate the homepage or a product page and look for <code>MerchantReturnPolicy</code>.</p>\n<h2>Spec reference</h2>\n<p>Google Search Central “Merchant return policy” structured data.</p>\n",
  "markdown": "# Return policy is declared\n\n`hasMerchantReturnPolicy` on the offer, or on your Organization, lets agents tell shoppers how returns work.\n\n## How to fix\n\nAdd a `MerchantReturnPolicy` (applicable country, return window, method, fees) once on your Organization markup, or on each Offer.\n\n## WooCommerce\n\nUse your SEO plugin's organization/return policy settings; otherwise add Organization JSON-LD with `hasMerchantReturnPolicy` site-wide.\n\n## How to verify\n\nValidate the homepage or a product page and look for `MerchantReturnPolicy`.\n\n## Spec reference\n\nGoogle Search Central “Merchant return policy” structured data.\n"
 },
 "products.shipping_details": {
  "title": "Offers include shipping details",
  "html": "<p><code>offers.shippingDetails</code> (OfferShippingDetails) tells agents delivery cost and time, a common shopper question.</p>\n<h2>How to fix</h2>\n<p>Add <code>shippingDetails</code> with <code>shippingRate</code>, <code>shippingDestination</code> and <code>deliveryTime</code>, or configure shipping in Google Merchant Center as well.</p>\n<h2>WooCommerce</h2>\n<p>Rank Math and Yoast WooCommerce SEO can output shipping details from your WooCommerce shipping zones; enable that option.</p>\n<h2>How to verify</h2>\n<p>Look for <code>shippingDetails</code> in the Offer.</p>\n<h2>Spec reference</h2>\n<p>Google Search Central “Product structured data” and schema.org <code>Product</code>/<code>Offer</code> (“Shipping details”).</p>\n",
  "markdown": "# Offers include shipping details\n\n`offers.shippingDetails` (OfferShippingDetails) tells agents delivery cost and time, a common shopper question.\n\n## How to fix\n\nAdd `shippingDetails` with `shippingRate`, `shippingDestination` and `deliveryTime`, or configure shipping in Google Merchant Center as well.\n\n## WooCommerce\n\nRank Math and Yoast WooCommerce SEO can output shipping details from your WooCommerce shipping zones; enable that option.\n\n## How to verify\n\nLook for `shippingDetails` in the Offer.\n\n## Spec reference\n\nGoogle Search Central “Product structured data” and schema.org `Product`/`Offer` (“Shipping details”).\n"
 }
};
